/// key belongs to another cluster.
(Model, Cmd?)? _handlePickerAcceptKey(KeyMsg msg) {
  switch (msg.key) {
    case 'enter':
    case 'tab':
      if (menuItems.isEmpty) return (this, null);
      return _acceptPickerAt(menuSelected);
    default:
      return null;
  }
}

