(Model, Cmd?)? _handleControlKey(KeyMsg msg) {
  return _handlePasteImageKey(msg) ??
      _handleSubmitKeys(msg) ??
      _handleQueueKeys(msg) ??
      _handleInterruptKeys(msg);
