  (Model, Cmd?)? _handleReadlineKey(KeyMsg msg) {
    final TuiLineEditor edited;
    switch (msg.key) {
      case 'ctrl+k':
        if (cursor >= inputText.length) return (this, null);
        edited = editor.killToLineEnd();
      case 'ctrl+y':
        if (!editor.canYank) return (this, null);
