_PromptKeyResult? _handleApprovalKillKey(TuiPromptState state, PromptKey key) {
  if (key is! PromptCtrlU) return null;
  if (state.approvalInput.isEmpty) return null;
  return (state: state.copyWith(approvalInput: ''), resolved: null);
}
_PromptKeyResult? _handleApprovalBackspaceKey(
  TuiPromptState state,
  PromptKey key,
) {
  if (key is! PromptBackspace) return null;
  final deleted = _backspacedBuffer(
    state.approvalInput,
    state.approvalInput.length,
  );
  if (deleted == null) return (state: state, resolved: null);
  return (state: state.copyWith(approvalInput: deleted.$1), resolved: null);
}
_PromptKeyResult? _handleApprovalNumberKey(
  TuiPromptState state,
  PromptKey key,
) {
  if (key is! PromptChar) return null;
  final note = state.approvalInput;
  const decisions = <String, ApprovalDecision>{
    '1': ApprovalDecision.approveOnce,
    '2': ApprovalDecision.approveAlways,
    '3': ApprovalDecision.deny,
  };
  final decision = decisions[key.text];
  if (decision == null) return null;
  return (
    state: state.copyWith(approvalInput: ''),
    resolved: ApprovalPromptAnswer(decision, note: note),
  );
}
_PromptKeyResult? _handleApprovalSelectorKey(
