        if (identical(edited, editor)) return (this, null);
      case 'ctrl+z':
        if (!editor.canUndo) return (this, null);
        edited = editor.undo();
      default:
        return null;
    }
    return (_updateMenuForInput(copyWith(editor: edited)), null);
