/// Picker page keys (pgup/pgdown jump to the first/last item); null when
/// the key belongs to another cluster.
(Model, Cmd?)? _handlePickerPageKey(KeyMsg msg) {
  switch (msg.key) {
    case 'pgup':
      return (copyWith(menuSelected: 0), null);
