_PromptKeyResult? _handleApprovalBackspaceKey(
  TuiPromptState state,
  PromptKey key,
) {
  if (key is! PromptBackspace) return null;
  final deleted = _backspacedBuffer(
    state.approvalInput,
    state.approvalInput.length,
