    // stays plain ASCII; existing `/help` output is byte-unchanged.
    final lower = filter.trim().toLowerCase();
    if (lower == 'hotkeys' || lower == 'keys' || lower == 'keybindings') {
      for (final line
          in tuiHotkeyTableLines(markdown: _useTui, darwin: tuiKeyHintDarwin)) {
