      ...r.trailing,
    ];
    if (tailLines.isEmpty) {
      _publishCleanViews();
      return;
    }
    final tailRows = <String>[];
    final tailStarts = <int>[];
    final rowOffset = _rows.length;
    final past = <int>[..._starts.sublist(0, _starts.length - 1)];
    for (final line in tailLines) {
