/// picker adds the one-line footer hint under the table.
int _writeMenuItems(StringBuffer b, int baseRow) {
  final (start, end) = _menuWindow();
  var row = baseRow;
  var lastGroup = '';
  if (start > 0) {
    b.writeln(_dim('  ↑ more'));
    row++;
  }
  for (var i = start; i < end; i++) {
    final group = menuItems[i].group;
    if (group.isNotEmpty && group != lastGroup) {
      b.writeln(_dim('  ── $group ──'));
      lastGroup = group;
    }
    b.writeln(_menuItemRow(menuItems[i], i == menuSelected));
    _hitRegions.add(
      TuiHitRegion(
        x: 0,
        y: row,
        w: termWidth,
        h: 1,
        kind: TuiRegionKind.menuRow,
        index: i,
      ),
    );
    row++;
  }
  if (end < menuItems.length) {
    b.writeln(_dim('  ↓ more'));
    row++;
  }
  if (_modelPickerFamilyOpen) {
    b.writeln(_dim(' $modelPickerFooterHint'));
    row++;
  }
  return row - baseRow;
}

/// True while the models picker (or its two-step provider page) is open —
/// the only pickers that carry the footer hint row.
bool get _modelPickerFamilyOpen =>
    menuOpen &&
    menuModelMode &&
    (pickerId == 'models' || pickerId == 'modelProvider');

/// One menu row (label + dim description, truncated to the width).
String _menuItemRow(MenuItem item, bool selected) {
  final desc = item.description.isNotEmpty ? ' ${item.description}' : '';
  final full = '${item.label}$desc';
  // Highlighted labels embed SGR runs; widths are VISIBLE cells (the
  // renderer measures stripped rows — vendor viewport.dart measures
  // `textWidth(stripAnsi(line))`), so measure and fit the stripped text:
  // counting the escape bytes as cells over-measured every fuzzy-matched
  // row ~3× and elided it to a few visible chars (issue #595).
  final plain = stripAnsi(full);
  final prefix = selected ? '${_accent('▸')} ' : '  ';
  if (tuiTextWidth(plain) <= termWidth - 2) {
    if (selected) {
      return '$prefix${_rearmSelection(item.label)}${_dim(desc)}';
    }
    return '$prefix${item.label}${_dim(desc)}';
  }
  // Truncated rows render stripped: fitting the styled string cut
  // mid-escape, leaking SGR into the rest of the line. The fitted text is
  // plain SGR-free, so wrap it in the selection accent first (gh-671) —
  // a long selected label keeps the selection cue too.
  final fitted = _fitWidth(plain, termWidth - 2);
  if (selected) return '$prefix${_rearmSelection(fitted)}';
  return '$prefix$fitted';
}

