  String? _indigoSgr;
  String? _dimSgr;
  static const _bold = '\x1b[1m';
  static const _italic = '\x1b[3m';
  static const _underline = '\x1b[4m';
  static const _strike = '\x1b[9m';
  static const _reset = '\x1b[0m';

